import math, pygame, sys

width = 1000
height = 600

print("Welcome to the Snell's Law interpreter!")

theta_1 = int(input("Please enter the incoming angle for θ_1: "))
if 0 < theta_1 < 91:
    theta_1 = 90 - theta_1
elif 90 < theta_1 < 181:
    theta_1 = 180 - theta_1
elif 180 < theta_1 < 271:
    theta_1 = 270 - theta_1
elif 270 < theta_1 < 361:
    theta_1 = 360 - theta_1
else:
    print(f"The refractive index of {theta_1} cannot be above 360.")

def sin(sin_value):
    return math.sin(math.radians(sin_value))

def arcsin(arcsin_value):
    return math.degrees(math.asin(arcsin_value))

n_1 = float(input("Please enter the refractive index for the top: "))
n_2 = float(input("Please enter the refractive index for the bottom: "))

def snell(snell_theta, snell_rf1, snell_rf2):
    return arcsin((snell_rf1 * sin(snell_theta)) / snell_rf2)

print(f"The outcoming angle for θ_2 is {snell(theta_1, n_1, n_2)}")

pygame.init()

screen = pygame.display.set_mode((width, height), pygame.RESIZABLE)

pygame.display.set_caption(f"Snell's Law, θ_1, θ_2 = {theta_1}, {snell(theta_1, n_1, n_2)}")

theta_1_start_point = pygame.math.Vector2(300, 300)

theta_1_vec = pygame.math.Vector2(-200, 0)
theta_1_vec.rotate_ip(theta_1)

theta_1_end_point = theta_1_start_point + theta_1_vec

theta_2_start_point = pygame.math.Vector2(500, 500)

theta_2_vec = pygame.math.Vector2(-200, 0)
theta_2_vec.rotate_ip(45)
theta_2_vec.rotate_ip(-(45-snell(theta_1, n_1, n_2)))

theta_2_end_point = theta_2_start_point + theta_2_vec

horizontal_start_point = pygame.math.Vector2(100, 300)

horizontal_vec = pygame.math.Vector2(400, 0)

horizontal_end_point = horizontal_start_point + horizontal_vec

vertical_start_point = pygame.math.Vector2(300, 100)

vertical_vec = pygame.math.Vector2(0, 600)

vertical_end_point = vertical_start_point + vertical_vec

running = True

while running:
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False
        elif event.type == pygame.KEYDOWN:
            if pygame.K_ESCAPE:
                running = False

    if running == False:
        sys.exit()

    screen.fill((0, 0, 0))

    pygame.draw.line(screen, (255, 255, 255), theta_1_start_point, theta_1_end_point, 5)
    pygame.draw.line(screen, (255, 255, 255), theta_2_start_point, theta_2_end_point, 5)
    pygame.draw.line(screen, (255, 255, 255), horizontal_start_point, horizontal_end_point, 5)
    pygame.draw.line(screen, (255, 255, 255), vertical_start_point, vertical_end_point, 5)
    
    pygame.display.flip()

pygame.quit()
